def qs(a):
    """min / p50 / p99 / max / n of a list of ints (None when empty)."""
    if len(a) == 0:
        return None
    a = np.sort(np.asarray(a, dtype=np.int64))
    return {'n': int(len(a)), 'min': int(a[0]), 'p50': int(a[len(a) // 2]), 'p99': int(a[int(0.99 * (len(a) - 1))]), 'max': int(a[-1])}


